// ── EDIT THIS CONFIG ONCE ─────────────────────────────────
const CONFIG = {
  BACKEND_URL: 'http://host.docker.internal:5001',
  AUTOMATION_API_KEY: 'paste-your-automation-api-key',
  fromEmail: 'offers@mediportbd.com',
  storeName: 'MediportBD',
  storeUrl: 'https://mediportbd.com',
  couponCode: 'COMEBACK5',   // create this coupon in admin panel first
  smsThreshold: 2000         // BDT carts above this also get SMS
};
// ──────────────────────────────────────────────────────────
return { json: { CONFIG } };

// Flatten one item per cart with a personalized email body.
const CONFIG = $('Setup').first().json.CONFIG;
const carts = $input.first().json.carts || [];
const out = [];
for (const c of carts) {
  if (!c.customer?.email) continue;
  const rows = (c.items || []).map(i => `
    <tr>
      <td>${i.name || 'Product'}</td>
      <td style="text-align:center">${i.qty}</td>
      <td style="text-align:right">৳${Number(i.price).toLocaleString()}</td>
    </tr>`).join('');
  const html = `
    <div style="font-family:Arial,sans-serif;max-width:560px;margin:auto">
      <h2>You left something behind, ${c.customer.name || 'there'} 👋</h2>
      <p>Your cart at ${CONFIG.storeName} is still waiting — worth <b>৳${Number(c.subtotal).toLocaleString()}</b>.</p>
      <table border="1" cellpadding="8" width="100%" style="border-collapse:collapse">
        <tr><th align="left">Item</th><th>Qty</th><th align="right">Price</th></tr>
        ${rows}
      </table>
      <p>Use code <b style="background:#fff3cd;padding:2px 8px">${CONFIG.couponCode}</b> for an extra 5% off:</p>
      <p><a href="${CONFIG.storeUrl}/cart" style="background:#0d6efd;color:#fff;padding:12px 28px;text-decoration:none;border-radius:6px;display:inline-block">Complete My Order</a></p>
      <p style="color:#888;font-size:12px">You receive this because you started checkout at ${CONFIG.storeName}.</p>
    </div>`;
  out.push({ json: { cartId: String(c.cartId), email: c.customer.email, name: c.customer.name || 'Customer', subtotal: c.subtotal, phone: c.customer.phone || null, html } });
}
return out;

// Collect all processed cartIds and mark them notified in the backend
const items = $input.all();
const cartIds = items.map(i => i.json.cartId).filter(Boolean);
return { json: { cartIds } };
